import{_ as e,c as r,o as t,a3 as n}from"./chunks/framework.yHbjT2zn.js";const m=JSON.parse('{"title":"엔터프라이즈 도입 FAQ & 기술 검토","description":"SyncCMS 도입 시 자주 묻는 질문(라이선스, 보안 심의, 유지보수, 기간계 연동)과 맞춤형 아키텍처 진단 신청 방법을 안내합니다.","frontmatter":{"title":"엔터프라이즈 도입 FAQ & 기술 검토","description":"SyncCMS 도입 시 자주 묻는 질문(라이선스, 보안 심의, 유지보수, 기간계 연동)과 맞춤형 아키텍처 진단 신청 방법을 안내합니다.","sort":7,"head":[["link",{"rel":"canonical","href":"https://empasy.io/docs/synccms/enterprise-faq.html"}]]},"headers":[],"relativePath":"synccms/enterprise-faq.md","filePath":"ko/synccms/enterprise-faq.md","lastUpdated":1787437782000}'),s={name:"synccms/enterprise-faq.md"};function o(i,a,l,c,h,p){return t(),r("div",null,[...a[0]||(a[0]=[n('<h1 id="엔터프라이즈-도입-faq-기술-검토" tabindex="-1">엔터프라이즈 도입 FAQ &amp; 기술 검토 <a class="header-anchor" href="#엔터프라이즈-도입-faq-기술-검토" aria-label="Permalink to “엔터프라이즈 도입 FAQ &amp; 기술 검토”">​</a></h1><p>SyncCMS 도입을 검토 중인 고객사 기술팀, 보안팀, 기획팀의 핵심 질문과 답변입니다.</p><hr><h2 id="자주-묻는-질문-faq" tabindex="-1">자주 묻는 질문 (FAQ) <a class="header-anchor" href="#자주-묻는-질문-faq" aria-label="Permalink to “자주 묻는 질문 (FAQ)”">​</a></h2><h3 id="q1-주요-비즈니스-소스코드가-제공되나요-기술-주권" tabindex="-1">Q1. 주요 비즈니스 소스코드가 제공되나요? (기술 주권) <a class="header-anchor" href="#q1-주요-비즈니스-소스코드가-제공되나요-기술-주권" aria-label="Permalink to “Q1. 주요 비즈니스 소스코드가 제공되나요? (기술 주권)”">​</a></h3><p><strong>A. 네, 투명하게 제공됩니다.</strong><br> SyncCMS는 블랙박스 바이너리 패키지가 아닌, 표준 Spring Boot 3 및 Vue 3 프레임워크 소스코드와 DB DDL 전체를 제공합니다. 도입 후 고객사 자체 개발팀이 비즈니스 로직을 자유롭게 수정·확장할 수 있습니다.</p><h3 id="q2-트래픽이나-사용자-수가-늘어나면-추가-라이선스-비용이-발생하나요" tabindex="-1">Q2. 트래픽이나 사용자 수가 늘어나면 추가 라이선스 비용이 발생하나요? <a class="header-anchor" href="#q2-트래픽이나-사용자-수가-늘어나면-추가-라이선스-비용이-발생하나요" aria-label="Permalink to “Q2. 트래픽이나 사용자 수가 늘어나면 추가 라이선스 비용이 발생하나요?”">​</a></h3><p><strong>A. 전혀 발생하지 않습니다 (추가 라이선스료 0원).</strong><br> 외산 SaaS(Contentful 등)와 달리 API 호출량이나 사용자 수에 비례한 종량 과금이 없습니다. 1회 도입으로 고객사의 영구적인 IT 자산으로 귀속됩니다.</p><h3 id="q3-외부-인터넷이-차단된-완전-폐쇄망-환경에서도-ai-기능이-동작하나요" tabindex="-1">Q3. 외부 인터넷이 차단된 완전 폐쇄망 환경에서도 AI 기능이 동작하나요? <a class="header-anchor" href="#q3-외부-인터넷이-차단된-완전-폐쇄망-환경에서도-ai-기능이-동작하나요" aria-label="Permalink to “Q3. 외부 인터넷이 차단된 완전 폐쇄망 환경에서도 AI 기능이 동작하나요?”">​</a></h3><p><strong>A. 네, 100% 안정적으로 동작합니다.</strong><br> 사내 인프라(vLLM / Ollama)에 오픈 가중치 모델(Llama-3, EXAONE, Solar)을 온프레미스로 탑재하므로 외부 인터넷 연결 없이도 AI 초안 생성, PII 마스킹, RAG 지식 인출이 안정적으로 작동합니다.</p><h3 id="q4-기존-사내-그룹웨어-전자결재와-erp-연동이-가능한가요" tabindex="-1">Q4. 기존 사내 그룹웨어 전자결재와 ERP 연동이 가능한가요? <a class="header-anchor" href="#q4-기존-사내-그룹웨어-전자결재와-erp-연동이-가능한가요" aria-label="Permalink to “Q4. 기존 사내 그룹웨어 전자결재와 ERP 연동이 가능한가요?”">​</a></h3><p><strong>A. 표준 결재 연계 파이프라인과 다중 DB 트랜잭션을 지원합니다.</strong><br> 콘텐츠 발행 전 사내 전자결재 승인선 연계 기안을 자동 생성하며, 승인 웹훅 수신 시 ERP DB와 실시간 동기화 배포됩니다.</p><hr><h2 id="맞춤형-아키텍처-사전-진단-도입-컨설팅-신청" tabindex="-1">맞춤형 아키텍처 사전 진단 &amp; 도입 컨설팅 신청 <a class="header-anchor" href="#맞춤형-아키텍처-사전-진단-도입-컨설팅-신청" aria-label="Permalink to “맞춤형 아키텍처 사전 진단 &amp; 도입 컨설팅 신청”">​</a></h2><p>고객사의 실제 인프라 환경(폐쇄망, 사내 AI, 기간계 결합)을 정밀 분석하고 최적의 연동 아키텍처와 맞춤 구축 방안을 사전에 무료로 진단해 드립니다.</p><ul><li><strong>도입 문의</strong>: <code>poh@empasy.com</code></li><li><strong>기술 지원</strong>: <code>0507-1360-8169</code></li><li><strong>회사 정보</strong>: (주)엠파시 솔루션개발팀 | Empasy SyncSeries</li></ul>',16)])])}const f=e(s,[["render",o]]);export{m as __pageData,f as default};
